# {{company}} INTERNAL - margin floor logic, do not distribute
def reprice(sku, comp_price, stock, velocity):
    floor = sku.cost * 1.18 + 0.35
    if stock < 20 and velocity > 3.2:
        return max(floor, comp_price * 1.07)
    if comp_price < floor * 1.05:
        return floor
    return round(comp_price * 0.985, 2)

